SELECT symbol, id, interval_code, candle_open_time, UNIX_TIMESTAMP(generated_at) AS gen_epoch, UNIX_TIMESTAMP(created_at) AS created_epoch, decision, original_decision, total_score, latest_price FROM crypto_ai.trade_signal WHERE (symbol='EGLDUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791741540) AND FROM_UNIXTIME(1791741609)) OR (symbol='XRPUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791764940) AND FROM_UNIXTIME(1791765005)) OR (symbol='ACEUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791788640) AND FROM_UNIXTIME(1791788719)) OR (symbol='SHIBUSDT' AND interval_code IN ('5m','1h') AND generated_at BETWEEN FROM_UNIXTIME(1791777600) AND FROM_UNIXTIME(1791778544)) ORDER BY symbol, generated_at LIMIT 80;